import {keys,list,write,projects,recordTask} from './state.mjs';
import {esc,icon,download,formatDate} from './ui.mjs';
const $=s=>document.querySelector(s);
const favoriteKey='paperknow-more-favorites';
const catalogue=[
 {id:'posting',name:'投稿准备',icon:'send',color:'blue',url:'#tool/posting',desc:'整理期刊要求、投稿材料与提交前检查清单。',input:'目标期刊与论文信息',output:'可编辑投稿材料清单',action:'创建投稿清单'},
 {id:'translation',name:'学术翻译',icon:'language',color:'mint',url:'#category/literature?tool=translation',desc:'统一管理原文与译文笔记，继续使用文献研读工作区。',action:'前往翻译整理'},
 {id:'resume',name:'学术简历',icon:'user',color:'orange',url:'#tool/resume',desc:'整理教育经历、研究项目、论文与学术成果。',input:'真实经历与成果',output:'可编辑简历草稿',action:'创建学术简历'}
];
const favorites=()=>list(favoriteKey).filter(id=>catalogue.some(t=>t.id===id));
const star=(filled=false)=>`<svg width="20" height="20" viewBox="0 0 24 24" fill="${filled?'currentColor':'none'}" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="m12 3 2.8 5.8 6.4.9-4.6 4.5 1.1 6.4-5.7-3-5.7 3 1.1-6.4L2.8 9.7l6.4-.9z"/></svg>`;
function favoriteButton(t){const selected=favorites().includes(t.id);return `<button class="more-star ${selected?'selected':''}" data-more-star="${t.id}" aria-pressed="${selected}" aria-label="${selected?'取消收藏':'收藏'}${t.name}">${star(selected)}</button>`;}
function card(t){return `<article class="card more-tool ${t.id==='translation'?'more-translation':''}"><span class="more-icon ${t.color}">${icon(t.icon,28)}</span><div class="more-tool-copy"><div class="more-title"><h3>${t.name}</h3><span class="more-pill">${t.id==='translation'?'复用文献与研读':'本地模板可用'}</span></div><p>${t.desc}</p>${t.input?`<div class="more-meta"><span>${icon('file',14)} 输入：${t.input}</span><span>${icon('folder',14)} 输出：${t.output}</span></div>`:'<small>当前可用：原文与译文笔记整理 · AI 翻译待接入</small>'}<footer><a href="${t.url}" class="${t.id==='translation'?'btn secondary':''}">${t.action} ${icon('arrow',16)}</a>${favoriteButton(t)}</footer></div></article>`;}
export function mountMore({modal,notify}){
 editor=null;
 $('.dashboard').innerHTML=`<div class="hub-heading"><div><h1>更多工具</h1><p>围绕投稿、学术表达与升学求职，找到下一步需要的支持。</p></div><button class="btn secondary" data-more-favorites>${star()} 我的收藏</button></div><div class="more-banner"><span class="more-banner-icon">${icon('send',30)}</span><div><h2>把研究成果，带到下一阶段</h2><p>整理投稿材料、准备学术简历，或继续处理文献中的语言问题。</p></div><span class="more-banner-art" aria-hidden="true">${icon('file',65)}${icon('book',45)}</span></div><section class="more-section"><header><h2>投稿与发表</h2><p>从材料整理开始，做好投稿准备</p></header><div class="more-grid">${card(catalogue[0])}<article class="card more-tool more-planned"><span class="more-icon purple">${icon('mail',28)}</span><div class="more-tool-copy"><div class="more-title"><h3>投稿信与审稿回复</h3><span class="more-pill gray">规划中</span></div><p>围绕真实研究贡献与审稿意见组织表达。</p><footer><span>待开放</span></footer></div></article></div></section><section class="more-section"><header><h2>学术表达</h2><p>与文献研读协同，保留原文与术语依据</p></header>${card(catalogue[1])}</section><section class="more-section"><header><h2>升学与求职</h2><p>用真实经历，呈现你的研究能力</p></header><div class="more-grid">${card(catalogue[2])}<aside class="card more-preparation"><span class="more-icon orange">${icon('folder',28)}</span><div><h3>先准备这些材料</h3><ul><li>教育与研究经历</li><li>项目职责与实际贡献</li><li>论文、奖项与成果链接</li></ul></div></aside></div></section><p class="more-footnote">${icon('help',17)} 模板工具可本地整理与保存；AI 功能以各工具页面的可用状态为准。</p>`;
 $('.dashboard').onclick=e=>{const b=e.target.closest('[data-more-star]');if(b){toggleFavorite(b.dataset.moreStar,notify);return;}if(e.target.closest('[data-more-favorites]'))showFavorites({modal,notify});};
}
function toggleFavorite(id,notify){try{const selected=favorites();write(favoriteKey,selected.includes(id)?selected.filter(x=>x!==id):[...selected,id]);document.querySelectorAll('[data-more-star]').forEach(b=>{const t=catalogue.find(t=>t.id===b.dataset.moreStar);if(!t)return;const chosen=favorites().includes(t.id);b.innerHTML=star(chosen);b.classList.toggle('selected',chosen);b.setAttribute('aria-pressed',chosen);b.setAttribute('aria-label',(chosen?'取消收藏':'收藏')+t.name);});notify(favorites().includes(id)?'已收藏到当前浏览器。':'已取消收藏。');}catch{notify('收藏保存失败，请检查浏览器存储空间。');}}
function showFavorites({modal,notify}){const selected=catalogue.filter(t=>favorites().includes(t.id));modal('我的工具收藏',`<p class="hub-footnote">收藏保存在当前浏览器，可随时取消。</p><div class="more-favorite-list">${selected.map(t=>`<div><span class="more-icon ${t.color}">${icon(t.icon,22)}</span><a href="${t.url}"><b>${t.name}</b><small>${t.action} →</small></a><button class="btn secondary" data-remove-favorite="${t.id}">取消收藏</button></div>`).join('')||'<p class="hub-empty">还没有收藏，点击工具卡片上的星标即可添加。</p>'}</div>`);$('#workspace-dialog-body').onclick=e=>{const b=e.target.closest('[data-remove-favorite]');if(b){toggleFavorite(b.dataset.removeFavorite,notify);showFavorites({modal,notify});}};}
const fields={
 posting:[['journal','目标期刊','例如：期刊全称；自行核对征稿范围'],['url','期刊官网 / 投稿要求链接','https://…'],['type','文章类型与篇幅要求','例如：研究论文；字数、图表、参考文献要求'],['authors','作者与通讯信息','按真实作者顺序填写，确认所有作者同意投稿'],['materials','正文、图表与数据材料','逐行记录文件名、版本及待准备材料'],['declarations','声明与授权核对','伦理审批、作者贡献、利益冲突、数据许可等适用要求'],['notes','投稿与返修安排','提交方式、目标日期、待确认事项']],
 resume:[['contact','姓名与联系方式','仅填写你希望呈现在简历中的信息'],['education','教育背景','学校、专业、学位、起止时间'],['direction','研究方向','研究问题、研究领域与个人兴趣'],['experience','研究项目与个人贡献','项目名称、时间、你的职责及可核实成果'],['publications','论文、报告与作品','标题、作者顺序、发表状态、年份、DOI / 链接'],['skills','专业技能','研究方法、软件、语言等真实技能'],['awards','奖项与其他经历','奖项名称、授予机构、时间；无则留空']]
};
const checkItems=['核对期刊范围与文章类型','核对正文、图表及篇幅要求','确认作者顺序与投稿授权','核对引文与参考文献','核对适用的伦理与利益冲突声明','核对数据、图片与材料使用许可','按期刊官网要求逐项核对提交材料'];
let editor=null;
let editorController;
export const moreHasWork=()=>Boolean(editor?.dirty);
export function clearMoreWork(){editorController?.abort();editor=null;const root=$('.dashboard');if(root)root.onclick=null;const body=$('#workspace-dialog-body');if(body)body.onclick=null;}
export function moreRouteGuard(target){if(!editor?.dirty)return true;const current=editor;current.ctx.modal('还有未保存的修改',`<p class="hub-description">保存后可从「我的成果」继续编辑。也可以留在本页，或放弃本次未保存修改。</p><div class="more-leave-actions"><button class="btn secondary" data-more-stay>继续编辑</button><button class="btn secondary" data-more-discard>放弃修改并离开</button><button class="btn primary" data-more-save-leave>保存并离开</button></div>`);$('[data-more-stay]').onclick=()=>$('#workspace-dialog').close();$('[data-more-discard]').onclick=()=>{current.dirty=false;$('#workspace-dialog').close();location.hash=target;};$('[data-more-save-leave]').onclick=()=>{if(current.save()){current.dirty=false;$('#workspace-dialog').close();location.hash=target;}};return false;}
if(typeof window!=='undefined')window.addEventListener('beforeunload',e=>{if(moreHasWork()){e.preventDefault();e.returnValue='';}});
export function mountMoreEditor(id,ctx,draftId,projectId=''){
 editorController?.abort();editorController=new AbortController();
 const loaded=list(keys.drafts).find(d=>String(d.id)===String(draftId)),name=id==='resume'?'学术简历':'投稿准备';
 let savedId=loaded?.id||null,createdAt=loaded?.createdAt||new Date().toISOString();const values=loaded?.moreTool?.values||{},checks=new Set(loaded?.moreTool?.checks||[]);
 editor={dirty:false,ctx};const current=editor;
 const legacyText=loaded&&!loaded.moreTool?(loaded.text||''):'';
 $('.dashboard').innerHTML=`<div class="hub-heading"><div><h1>${name}</h1><p>${id==='resume'?'用真实经历组织学术简历，保留你的实际贡献。':'按目标期刊的真实要求，整理材料与提交前核对事项。'}</p></div><a class="btn secondary" href="#category/more">返回更多工具</a></div><div class="more-editor-boundary">${icon('shield',18)} 本地整理 · 未调用 AI · 可编辑、保存与导出文本${id==='posting'?' · 不自动投稿或核验期刊':''}</div><div class="more-editor-grid"><section class="card more-editor-input"><h2>${id==='resume'?'整理简历信息':'整理投稿信息'}</h2><form id="more-editor-form" class="hub-form"><label for="more-project">所属项目（可选）</label><select id="more-project"><option value="">未归入项目</option>${projects().map(p=>`<option value="${esc(p.id)}" ${p.id===(loaded?.projectId||projectId)?'selected':''}>${esc(p.name)}${p.status==='archived'?'（已归档）':''}</option>`).join('')}</select><label for="more-title">${id==='resume'?'简历名称':'论文 / 投稿任务名称'} *</label><input id="more-title" required maxlength="150" value="${esc(loaded?.title||'')}" placeholder="${id==='resume'?'例如：李同学 · 硕士申请简历':'填写真实论文题目或投稿任务名称'}">${fields[id].map(([key,label,placeholder])=>`<label for="more-field-${key}">${label}</label>${key==='url'?`<input id="more-field-${key}" type="url" maxlength="2000" value="${esc(values[key]||'')}" placeholder="${esc(placeholder)}">`:`<textarea id="more-field-${key}" maxlength="4000" rows="3" placeholder="${esc(placeholder)}">${esc(values[key]||'')}</textarea>`}`).join('')}${id==='posting'?`<fieldset class="more-checks"><legend>提交前人工核对</legend><p>勾选表示你已核对，不代表系统验证通过。</p>${checkItems.map((label,i)=>`<label><input type="checkbox" data-more-check="${i}" ${checks.has(i)?'checked':''}>${label}</label>`).join('')}</fieldset>`:''}<button class="btn primary" type="submit">${id==='resume'?'整理简历草稿':'整理投稿清单'} ${icon('arrow',16)}</button><p class="hub-footnote">重新整理会替换右侧内容，可先保存或导出已有文本。</p></form></section><section class="card more-editor-output"><header><h2>${id==='resume'?'简历草稿':'投稿清单'}</h2><span class="more-pill">可编辑</span></header><p>${id==='resume'?'仅整理你填写的经历，不生成虚构成果。空白栏目可在成稿时删除。':'待确认事项会保留在清单中；以目标期刊官网最新要求为准。'}</p><label class="sr-only" for="more-result">编辑${name}文本</label><textarea id="more-result" maxlength="40000" rows="24" placeholder="填写左侧信息并整理，或直接在这里编辑你的文本。">${esc(loaded?.text||legacyText)}</textarea><div class="more-editor-actions"><button class="btn primary" id="more-save">保存到我的成果</button><button class="btn secondary" id="more-export">导出 TXT</button></div><p class="hub-error" id="more-error" role="alert"></p><p class="hub-footnote" id="more-status" role="status">${loaded?'已载入本地保存内容。':'内容保存在当前浏览器，请及时导出备份。'}</p>${legacyText?'<p class="hub-footnote">旧版简历文本已保留，可继续编辑；左侧结构字段尚未填写。</p>':''}<a class="more-results-link" href="#assets">查看我的成果 ${icon('arrow',15)}</a></section></div>`;
 const collect=()=>Object.fromEntries(fields[id].map(([key])=>[key,$('#more-field-'+key).value.trim()]));
 const title=()=>$('#more-title').value.trim();
 const fail=message=>{$('#more-error').textContent=message;ctx.notify(message);return false;};
 const save=()=>{if(!title())return fail('请填写名称。');const text=$('#more-result').value.trim();if(!text)return fail('请先整理或填写右侧文本。');const now=new Date().toISOString(),item={...loaded,id:savedId||crypto.randomUUID(),title:title(),tool:id,projectId:$('#more-project').value,text,html:text.split('\n').map(l=>`<p>${esc(l)}</p>`).join(''),moreTool:{version:1,values:collect(),checks:[...document.querySelectorAll('[data-more-check]:checked')].map(b=>Number(b.dataset.moreCheck))},createdAt,updatedAt:now,date:formatDate(now)};try{const rows=list(keys.drafts),i=rows.findIndex(d=>String(d.id)===String(item.id));if(i>=0)rows[i]=item;else rows.unshift(item);write(keys.drafts,rows);savedId=item.id;current.dirty=false;$('#more-error').textContent='';$('#more-status').textContent='已保存到当前浏览器，可从「我的成果」继续编辑。';try{recordTask({id:'draft-'+item.id,title:item.title,projectId:item.projectId,kind:name+' · 本地保存',status:'completed',url:'#draft/'+encodeURIComponent(item.id)});}catch{$('#more-status').textContent+=' 任务记录未保存。';}return true;}catch{return fail('保存失败，请导出文本备份并检查浏览器存储空间。');}};
 current.save=save;
 $('.dashboard').addEventListener('input',e=>{current.dirty=true;$('#more-status').textContent=e.target.closest('#more-editor-form')&&$('#more-result').value.trim()?'信息已修改；右侧文本不会自动更新，请重新整理或手动同步后保存。':'有未保存的修改。';},{signal:editorController.signal});
 $('.dashboard').addEventListener('change',()=>{current.dirty=true;$('#more-status').textContent='有未保存的修改。';},{signal:editorController.signal});
 $('#more-editor-form').onsubmit=e=>{e.preventDefault();const v=collect();const content=`${title()}\n${name} · 本地整理\n\n${fields[id].filter(([key])=>id==='posting'||v[key]).map(([key,label])=>`${label}\n${v[key]||'待填写 / 待确认'}`).join('\n\n')}${id==='posting'?'\n\n提交前人工核对\n'+checkItems.map((label,i)=>`${document.querySelector(`[data-more-check="${i}"]`).checked?'[已人工核对]':'[待核对]'} ${label}`).join('\n'):''}`;const apply=()=>{$('#more-result').value=content;current.dirty=true;$('#more-error').textContent='';$('#more-status').textContent='已按当前输入整理，可直接编辑后保存。';};if($('#more-result').value.trim()){ctx.modal('替换右侧文本',`<p class="hub-description">重新整理会使用左侧当前信息替换右侧文本。手工修改过的内容请先保存或导出。</p><div class="more-leave-actions"><button class="btn secondary" data-more-cancel>保留现有文本</button><button class="btn primary" data-more-rebuild>确认重新整理</button></div>`);$('[data-more-cancel]').onclick=()=>$('#workspace-dialog').close();$('[data-more-rebuild]').onclick=()=>{apply();$('#workspace-dialog').close();};}else apply();};
 $('#more-save').onclick=save;
 $('#more-export').onclick=()=>{const text=$('#more-result').value.trim();if(!text){fail('请先整理或填写右侧文本。');return;}download((title()||name)+'.txt',text);$('#more-status').textContent='已发起文本下载，请确认文件已保存；导出不会自动保存草稿。';};
}
